-- [제원·MBTI 반영] 白瀬のの (shirase-nono, 2026-10-12): 종족:요정 (妖精)
UPDATE portal_profiles SET data='{"slug":"shirase-nono","displayName":"白瀬のの","description":"10/12日21:00〜初配信✨️✨️\n\n見つけてくださってありがとうございます✨️\n\n夜明けのあいだで生まれた 妖精系VTuber🪞✨️\n白瀬ののです.ᐟ.ᐟ✨️\n\n地球の夜明けを見届けるために\n妖精の国からやって来ました🧚‍♀️🪽\n\n🪞𝐥𝐢𝐤𝐞✨️\n牛乳〜❕🥛  \n\n🪞𝐃𝐨𝐧&#39;𝐭 𝐥𝐢𝐤𝐞😖💦\n【ねぎ】がつく食べもの…😖\n\nねぎ…ながねぎ…たまねぎ… \n\n\n🪞配信内容💭\n主に朝活☀️ おはよう配信など…✨️\nゲームやASMR配信も予定しております✨️🪞\n\n夜になると……❕乞うご期待✨️💭\n\n静かな夜明けを のの と一緒に✧︎*。\n\n\n𝐄𝐧𝐠𝐥𝐢𝐬𝐡 \n\nThank you for finding me! ✨️\n\nA fairy-like VTuber born during the dawn 🪞✨️\nI&#39;m Nono Sirose. ᐟ.ᐟ✨️\n\nI emerged from fairyland to witness the dawn of the Earth. 🧚‍♀️🪽\n\n🪞Scheduled to debut around spring next year ✨️\n🪞Preparing for my first stream ✨️💭\n\n🪞𝐥𝐢𝐤𝐞✨️\nMilk~❕🥛\n\n🪞𝐃𝐨𝐧&#39;𝐭𝐥𝐢𝐤𝐞😖💦\n[Green onions] Something to grow and eat...😖\n\nGreen onions...long onions...onions...\n\n🪞Streaming content 💭\nMostly morning activities ☀️ Morning streams and more...✨️\nGame and ASMR streams are also planned!✨️🪞\n\nWhen night falls...❕ Stay tuned!✨️💭\n\nSpend a quiet dawn together!✧︎*","avatarUrl":"https://yt3.googleusercontent.com/W9T4eOeOuKkyehX7E378KzkdeFZdNyrh0Nypbl7jXVZ9Q90uNdi23MbUwLTGFU4hObmXhlyX3A=s900-c-k-c0x00ffffff-no-rj","agency":"","platform":"YOUTUBE","channelUrl":"https://www.youtube.com/@%E7%99%BD%E7%80%AC%E3%81%AE%E3%81%AE","countryCode":"","languages":[],"tags":[],"xUrl":"","dateState":"FIXED","debutDate":"2026-10-12","debutTime":"21:00","timezone":"Asia/Seoul","startAtUtc":"2026-10-12T12:00:00.000Z","targetMonth":"2026-10","ownerVerified":false,"source":"EXISTING","details":{"species":"요정 (妖精)","oshiMark":"🪞✨️","종족":"요정 (妖精)","오시마크":"🪞✨️"}}', updated_at=CURRENT_TIMESTAMP WHERE slug='shirase-nono' OR channel_url='https://www.youtube.com/@%E7%99%BD%E7%80%AC%E3%81%AE%E3%81%AE';
